import json
from typing import Any, Dict

def _offers_of(obj):
    if not isinstance(obj, dict):
        return []
    offers = obj.get('offers')
    if isinstance(offers, list):
        out = []
        for i, o in enumerate(offers, start=1):
            if not isinstance(o, dict):
                continue
            e = dict(o)
            e.setdefault('offer_seq', i)
            out.append(e)
        return out
    return [obj]

def _join(v):
    if isinstance(v, list):
        return ','.join(str(x) for x in v if str(x))
    return str(v or '')

async def main(args):
    raw = args.params['query_list']
    if not isinstance(raw, str):
        raw = json.dumps(raw, ensure_ascii=False)
    record_json = ''
    offer_id = ''
    global_id = ''
    try:
        arr = json.loads(raw)
        if isinstance(arr, list) and arr:
            first = arr[0]
            if isinstance(first, dict):
                record_json = str(first.get('result_json') or '')
        elif isinstance(arr, dict):
            record_json = str(arr.get('result_json') or '')
    except Exception:
        record_json = ''
    if not record_json:
        record_json = raw
    try:
        inner = json.loads(record_json)
        if isinstance(inner, dict):
            offers = _offers_of(inner)
            if offers:
                offer_id = str(offers[0].get('offer_id') or offers[0].get('offerId') or '')
            ids = []
            normalized = []
            for idx, o in enumerate(offers, start=1):
                gid = _join(o.get('globalId') or o.get('global_id') or '')
                oid = str(o.get('offer_id') or o.get('offerId') or '')
                oname = str(o.get('offer_name') or o.get('offerName') or '')
                if gid:
                    ids += [x for x in gid.split(',') if x]
                # offer_seq 兜底：上游封包缺失时按位置补序号，避免逐品标题全部退化为「商品1」
                seq = o.get('offer_seq')
                if seq in (None, ''):
                    seq = idx
                normalized.append({'offer_seq': seq,
                                   'offer_id': oid, 'offer_name': oname, 'globalId': gid})
            if not ids:
                ids = [x for x in _join(inner.get('globalId') or inner.get('global_id') or '').split(',') if x]
            global_id = ','.join(ids)
            offers_json = json.dumps(normalized, ensure_ascii=False)
        else:
            offers_json = '[]'
    except Exception:
        offer_id = ''
        global_id = ''
        offers_json = '[]'
    ret: Output = {
        "record_json": record_json,
        "offer_id": offer_id,
        "offer_name": str((offers[0].get('offer_name') or offers[0].get('offerName') or '') if offers else ''),
        "globalId": global_id,
        "offers": offers_json
    }
    return ret

import json
import urllib.request
from typing import Any, Dict

PROGRESS_URL = 'http://10.86.13.201:31281/api/v1/appstore/test/offer/progress'

def _load(v):
    if isinstance(v, list):
        return v
    if isinstance(v, dict):
        return [v]
    if not isinstance(v, str) or not v.strip():
        return []
    try:
        obj = json.loads(v)
        if isinstance(obj, dict) and isinstance(obj.get('offers'), list):
            return obj['offers']
        return obj if isinstance(obj, list) else ([obj] if isinstance(obj, dict) else [])
    except Exception:
        return []

def _int(v, default=0):
    try:
        return int(str(v).strip())
    except Exception:
        return default

def _bar(ratio, width=20):
    filled = int(round(width * ratio))
    if filled < 0:
        filled = 0
    if filled > width:
        filled = width
    return '█' * filled + '░' * (width - filled)

def _one(item):
    # 单商品进度快照 -> (归一 dict, 是否终态, 展示行)
    seq = item.get('offer_seq')
    gid = str(item.get('globalId') or item.get('global_id') or '')
    # EOP 真实出参：业务体在 resultObject 内（{resultCode, resultObject, resultMsg}）；
    # 兼容包裹层级：resultObject > progress > item 本体（逐层回退，保证 mock/real 同构）
    ro = item.get('resultObject')
    if isinstance(ro, dict):
        r = ro
    elif isinstance(item.get('progress'), dict):
        r = item.get('progress')
    else:
        r = item
    # 后端逐品返回业务错误（如 resultCode=1 查无对应测试任务）：标记 error，避免误报「处理中 0/0」
    rc = str(item.get('resultCode') or '').strip()
    err = rc != '' and rc != '0'
    err_msg = str(item.get('resultMsg') or '').strip() if err else ''
    if err:
        info = {'offer_seq': seq, 'globalId': gid, 'done': False, 'failed': True,
                'is_final': False, 'error': True, 'errorMsg': err_msg,
                'totalSceneCount': 0, 'finishedSceneCount': 0, 'failedSceneCount': 0,
                'totalSteps': 0, 'activeIndex': 0}
        line = ('  【商品%s】❌ 查询失败\n'
                '    原因：%s\n'
                '    流水号：%s（请重新发起测试）' % (
                    seq if seq not in (None, '') else '1', err_msg or '测试任务已失效', gid or '-'))
        return info, False, line
    total_scene = _int(r.get('totalSceneCount'))
    finished_scene = _int(r.get('finishedSceneCount'))
    failed_scene = _int(r.get('failedSceneCount'))
    total_step = _int(r.get('totalSteps'))
    active = _int(r.get('activeIndex'))
    done = str(r.get('done', '')).lower() == 'true'
    failed = str(r.get('failed', '')).lower() == 'true'
    is_final = done or (total_scene > 0 and finished_scene >= total_scene)
    if total_scene > 0:
        ratio = float(finished_scene) / float(total_scene)
    else:
        ratio = 1.0 if is_final else 0.0
    if is_final:
        state = '已完成' if not failed else '已完成（存在失败场景）'
        icon = '✅' if not failed else '❌'
    else:
        state = '处理中'
        icon = '⏳'
    line = ('  【商品%s】%s %s\n'
            '    进度：%s %d%%（场景 %d/%d，失败 %d）\n'
            '    步骤：%d/%d%s\n'
            '    流水号：%s' % (
                seq if seq not in (None, '') else '1', icon, state,
                _bar(ratio), int(round(ratio * 100)),
                finished_scene, total_scene, failed_scene,
                active, total_step, ('（失败于第 %d 步）' % (active + 1)) if failed else '',
                gid or '-'))
    info = {'offer_seq': seq, 'globalId': gid, 'done': done, 'failed': failed,
            'is_final': is_final, 'error': False,
            'totalSceneCount': total_scene,
            'finishedSceneCount': finished_scene, 'failedSceneCount': failed_scene,
            'totalSteps': total_step, 'activeIndex': active}
    return info, is_final, line

async def main(args):
    offers = _load(args.params.get('offers'))
    offers = [o for o in offers if isinstance(o, dict) and str(o.get('globalId') or '')]
    if not offers:
        ret: Output = {'done': 'false', 'failed': 'true', 'is_final': 'false',
                       'progress_text': '未获取到测试流水号 globalId，请先发起测试（环节6a）。',
                       'fail_reason': '缺少测试流水号 globalId，请先发起测试', 'offers': '[]'}
        return ret
    try:
        body = json.dumps({'offers': [{'offer_seq': o.get('offer_seq'),
                                       'globalId': o.get('globalId')} for o in offers]}).encode('utf-8')
        req = urllib.request.Request(PROGRESS_URL, data=body,
                                     headers={'Content-Type': 'application/json'})
        with urllib.request.urlopen(req, timeout=30) as http_resp:
            resp = json.loads(http_resp.read().decode('utf-8'))
    except Exception as e:
        ret: Output = {'done': 'false', 'failed': 'true', 'is_final': 'false',
                       'progress_text': '查询测试进度失败：%s' % str(e)[:200],
                       'fail_reason': '查询测试进度失败', 'offers': '[]'}
        return ret
    items = (resp.get('offers') if isinstance(resp, dict) else None) or []
    by_gid = {}
    by_seq = {}
    for it in items:
        if isinstance(it, dict):
            gid = str(it.get('globalId') or it.get('global_id') or '')
            if gid:
                by_gid[gid] = it
            by_seq[str(it.get('offer_seq'))] = it
    lines = []
    infos = []
    all_final = True
    any_failed = False
    any_error = False
    for o in offers:
        # 首选按 globalId 匹配（唯一字符串，规避 offer_seq 数值/字符串类型漂移导致的匹配失败）
        it = by_gid.get(str(o.get('globalId') or ''))
        if it is None:
            it = by_seq.get(str(o.get('offer_seq')))
        if it is None:
            it = {'offer_seq': o.get('offer_seq'), 'globalId': o.get('globalId')}
        info, is_final, line = _one(it)
        infos.append(info)
        lines.append(line)
        if not is_final:
            all_final = False
        if info['failed']:
            any_failed = True
        if info.get('error'):
            any_error = True
    if all_final:
        head = '■ 测试已结束，正在获取测试结果……'
    elif any_error:
        head = '■ 查询异常：部分测试任务已失效（后端查无对应流水号，可能已重启或超时），请重新发起测试（环节6a）'
    else:
        head = '■ 测试进行中，请稍后回复【查询测试结果】续查'
    progress_text = head + '\n\n' + '\n'.join(lines)
    ret: Output = {
        'done': 'true' if all_final else 'false',
        'failed': 'true' if any_failed else 'false',
        'is_final': 'true' if all_final else 'false',
        'progress_text': progress_text,
        'fail_reason': ('测试任务失效，请重新发起' if any_error else ('存在失败场景' if any_failed else '')),
        'offers': json.dumps(infos, ensure_ascii=False),
    }
    return ret

import json
from typing import Any, Dict

def _load(v):
    if isinstance(v, list):
        return v
    if isinstance(v, dict):
        return [v]
    if not isinstance(v, str) or not v.strip():
        return []
    try:
        obj = json.loads(v)
        if isinstance(obj, dict) and isinstance(obj.get('offers'), list):
            return obj['offers']
        return obj if isinstance(obj, list) else ([obj] if isinstance(obj, dict) else [])
    except Exception:
        return []

def _norm(item, idx):
    # EOP 真实出参业务体在 resultObject 内（{resultCode, resultObject, resultMsg}）；
    # 兼容包裹层级：resultObject > result > item 本体（逐层回退，mock/real 同构）
    ro = item.get('resultObject')
    if isinstance(ro, dict):
        r = ro
    elif isinstance(item.get('result'), dict):
        r = item.get('result')
    else:
        r = item
    scenes = []
    raw_scenes = r.get('testScenes') if isinstance(r, dict) else None
    if not isinstance(raw_scenes, list):
        raw_scenes = []
    for s in raw_scenes:
        if not isinstance(s, dict):
            continue
        pts = []
        for p in (s.get('testCasePointResults') or []):
            if not isinstance(p, dict):
                continue
            pts.append({
                'testCaseName': str(p.get('testCaseName') or ''),
                'testPointNbr': str(p.get('testPointNbr') or ''),
                'testPointName': str(p.get('testPointName') or ''),
                'presetValue': str(p.get('presetValue') or ''),
                'testValue': str(p.get('testValue') or ''),
                'resultCode': str(p.get('resultCode') or ''),
                'resultMsg': str(p.get('resultMsg') or ''),
            })
        rel = s.get('objTestSceneRel') if isinstance(s.get('objTestSceneRel'), dict) else {}
        scenes.append({
            'testSceneNbr': str(s.get('testSceneNbr') or ''),
            'testSceneName': str(s.get('testSceneName') or ''),
            'testSceneDesc': str(s.get('testSceneDesc') or ''),
            'testCaseCount': s.get('testCaseCount'),
            'successTestCaseCount': s.get('successTestCaseCount'),
            'failTestCaseCount': s.get('failTestCaseCount'),
            'relResultCode': str(rel.get('resultCode') or ''),
            'relResultMsg': str(rel.get('resultMsg') or ''),
            'points': pts,
        })
    return {
        'offer_seq': item.get('offer_seq') if item.get('offer_seq') not in (None, '') else idx,
        'globalId': str(item.get('globalId') or r.get('globalId') or ''),
        'offerId': str(r.get('offerId') or item.get('offer_id') or ''),
        'offerName': str(r.get('offerName') or r.get('offerId') or item.get('offer_id') or ''),
        'testRequestId': str(r.get('testRequestId') or ''),
        'resultCode': str(r.get('resultCode') or ''),
        'resultMsg': str(r.get('resultMsg') or ''),
        'testScenes': scenes,
    }

async def main(args):
    offers = _load(args.params.get('result_offers'))
    out = []
    for idx, it in enumerate(offers, start=1):
        if isinstance(it, dict):
            out.append(_norm(it, idx))
    payload = json.dumps(out, ensure_ascii=False)
    ret: Output = {'offers': payload, 'result_list': payload}
    return ret

